  // Deep diagnose for failed workflows — runs DeepAnalysisAgent multi-round tool-use loop.
  // Slower (~8-30s) and more expensive (~$0.008) than /error-summary; surfaced as an
  // opt-in "Get a deeper diagnosis" button on the failure card.
  app.post("/api/workflows/:invocationId/deep_diagnose", async (req, res) => {
    try {
      const galaxyUrl = process.env.GALAXY_URL || "http://localhost:8081";
      const resp = await fetch(
        `${galaxyUrl}/api/workflows/${encodeURIComponent(req.params.invocationId)}/deep_diagnose`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: AbortSignal.timeout(60000),  // 60s — multi-round agent + LLM
        }
      );
      if (resp.ok) {
        return res.json(await resp.json());
      }
      return res.status(resp.status).json({ available: false, root_cause: `Backend returned ${resp.status}` });
    } catch (err: any) {
      return res.json({ available: false, root_cause: `Deep diagnose request failed: ${String(err?.message ?? err)}` });
    }
  });

  // SSE endpoint for LangGraph pipeline task-status events.
  // The Python backend publishes to Redis channel biomate:pipeline:{id};
  // this endpoint relays those events to the browser.
  app.get("/api/pipelines/:pipelineId/events", async (req, res) => {
    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache, no-transform");
    res.setHeader("Connection", "keep-alive");
    res.setHeader("X-Accel-Buffering", "no");
    res.flushHeaders?.();

    // Send a ready event immediately so the client knows the channel is open
    res.write(`event: ready\ndata: {"ok":true}\n\n`);

    // If Redis is available, subscribe to the pipeline channel
    let redisSub: any = null;
    try {
      const { getRedisClient } = await import('./redis-session');
      const client = getRedisClient?.();
      if (client) {
        redisSub = client.duplicate();
        redisSub.subscribe(`biomate:pipeline:${req.params.pipelineId}`);
        redisSub.on("message", (_chan: string, msg: string) => {
          res.write(`data: ${msg}\n\n`);
        });
      }
    } catch (e) {
      console.warn('[PipelineSSE] Redis not available, events will not relay:', e);
    }

    // Heartbeat every 30 s to keep connection alive through proxies
    const heartbeat = setInterval(() => {
      res.write(`: heartbeat\n\n`);
    }, 30000);

    req.on("close", () => {
      clearInterval(heartbeat);
      redisSub?.quit?.();
    });
  });

  // Internal endpoint: Python backend POSTs here to push QC gate / phase events
  // to SSE clients.  Not authenticated — only reachable from localhost.
  app.post("/internal/sse-inject", (req: any, res: any) => {
    const { invocation_id, event_type, data } = req.body || {};
    if (!invocation_id || !event_type || data === undefined) {
      return res.status(400).json({ error: 'Missing invocation_id, event_type, or data' });
    }
    sseManager.injectRawEvent(String(invocation_id), String(event_type), data);
    res.json({ ok: true });
  });

  // Internal — Galaxy's orphan_finalizer (L3 poller post-completion) pushes
  // terminal status into the frontend execution_runs Postgres row. Without
  // this the frontend stays "running" forever even though Redis + Galaxy
  // logs show the workflow finalized. See
  // backend/lib/galaxy/ai/runs/orphan_finalizer.py.
  app.post("/internal/runs/by-invocation/:invId/status", async (req: any, res: any) => {
    const { invId } = req.params;
    const { status, returncode, completed_at, finalized_by } = req.body || {};
    if (!status) {
      return res.status(400).json({ error: 'Missing status' });
    }
    try {
      const run = await storage.getExecutionRunByGalaxyId(String(invId));
      if (!run) {
        return res.status(404).json({ error: 'execution_run not found for invocation', invId });
      }
      const completedAtDate = (typeof completed_at === 'number' && completed_at > 0)
        ? new Date(completed_at * 1000)
        : new Date();
      await storage.updateExecutionRun(run.id, {
        execution: {
          ...(run as any).execution,
          status: String(status),
          completedAt: completedAtDate,
          returncode: typeof returncode === 'number' ? returncode : undefined,
          finalizedBy: finalized_by ? String(finalized_by) : 'orphan_poller',
        },
      } as any);

      // Persist workflow metadata to chat_sessions.workflows on completion.
      if (status === 'completed' && run.chatSessionId) {
        try {
          const wfName = (run as any).workflowName ||
                         (run as any).workflowDefinition?.name ||
                         (run as any).workflowDefinition?.chain_name ||
                         'Workflow';
          const wfEntry = JSON.stringify([{
            workflow_id: run.id,
            workflow_name: wfName,
            status: 'completed',
          }]);
          await pool.query(
            `UPDATE chat_sessions SET workflows = $1::jsonb, last_activity = NOW()
             WHERE session_id = $2`,
            [wfEntry, run.chatSessionId]
          );
          console.log(`[OrphanFinalizer] Wrote workflow entry to chat_sessions for session ${run.chatSessionId}`);
        } catch (sessErr: any) {
          console.error('[OrphanFinalizer] Failed to update chat_sessions.workflows:', sessErr?.message);
        }
      }

      // Auto-save a completed project-scoped run's outputs into its project
      // Files (idempotent; no-op when the run has no project).
      if (status === 'completed') { void autoSaveCompletedRunOutputs(run); }

      return res.json({ ok: true, runId: run.id, status });
    } catch (e: any) {
      return res.status(500).json({ error: 'update failed', message: e?.message ?? String(e) });
    }
  });

  // Proxy for CryoSPARC status endpoint — frontend can poll run status directly
  app.get("/api/cryosparc/gpu_metrics", async (_req: any, res: any) => {
    try {
      const response = await fetch(
        `${process.env.GALAXY_URL || 'http://localhost:8081'}/api/cryosparc/gpu_metrics`,
        { headers: { 'X-API-Key': process.env.GALAXY_API_KEY || '' } }
      );
      const data = await response.json();
      return res.status(response.status).json(data);
    } catch (err: any) {
      return res.status(502).json({ error: 'GPU metrics proxy error', gpus: [] });
    }
  });

  app.get("/api/cryosparc/status/:runId", async (req: any, res: any) => {
    try {
      const response = await fetch(
        `${process.env.GALAXY_URL || 'http://localhost:8081'}/api/cryosparc/status/${req.params.runId}`,
        { headers: { 'X-API-Key': process.env.GALAXY_API_KEY || '' } }
      );
      const data = await response.json();
      return res.status(response.status).json(data);
    } catch (err: any) {
      return res.status(502).json({ error: 'CryoSPARC status proxy error' });
    }
  });

  // Proxy for QC gate endpoints — frontend POSTs to /api/qc-gates/:id/decision
  // which must be forwarded to the Galaxy backend. No dedicated route existed before.
  // Proxy for QC profiles list — GET /api/qc/profiles → Galaxy /api/qc/profiles
  app.get("/api/qc/profiles", async (_req: any, res: any) => {
    try {
      const response = await galaxyAPIProxy.client.get("/api/qc/profiles");
      return res.status(response.status).json(response.data);
    } catch (err: any) {
      const status = err.response?.status || 502;
      return res.status(status).json(err.response?.data || { error: 'QC profiles proxy error' });
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // Drug Discovery API — wildcard proxy to Galaxy/FastAPI backend
  // Covers all routes from lib/galaxy/ai/drug_discovery/api_router.py:
  //   POST   /api/drug-discovery/campaigns
  //   GET    /api/drug-discovery/model-validation/:model_type
  //   GET    /api/drug-discovery/audit
  //   GET    /api/drug-discovery/audit/verify
  //   GET    /api/drug-discovery/audit/export
  //   GET    /api/drug-discovery/esig/status
  //   POST   /api/drug-discovery/esig/enroll
  //   POST   /api/drug-discovery/esig/enroll/verify
  //   POST   /api/drug-discovery/:id/esig/sign
  //   GET    /api/drug-discovery/:id/retrain/status
  //   POST   /api/drug-discovery/:id/retrain/start|stop|trigger
  //   GET    /api/drug-discovery/:id/virtual-library
  //   POST   /api/drug-discovery/:id/virtual-library (new body)
  //   POST   /api/drug-discovery/:id/ind-assembly
  //   GET    /api/drug-discovery/:id/compounds
  //   GET    /api/drug-discovery/:id/export/cro-order
  //   POST   /api/drug-discovery/:id/ingest-assay  (multipart handled below)
  //   GET    /api/drug-discovery/availability
  // ─────────────────────────────────────────────────────────────────────────
  app.all("/api/drug-discovery/*", optionalAuth, async (req: any, res: any) => {
    try {
      const galaxyUrl = process.env.GALAXY_URL || 'http://localhost:8081';
      // Only a path under /api/drug-discovery (proxy-path.ts).
      const target = proxyTarget(req, '/api/drug-discovery');
      if (!target.ok) return rejectProxyPath(res, target);
      const targetPath = target.path; // /api/drug-discovery/...
      const method = req.method.toUpperCase();
      const fullPath = `${targetPath}${target.query}`;

      // Forward with user's Galaxy API key if available
      const headers: Record<string, string> = {
        'Content-Type': req.headers['content-type'] || 'application/json',
      };

      const fetchOpts: RequestInit = {
        method,
        headers,
        signal: AbortSignal.timeout(120000),
      };

      if (method !== 'GET' && method !== 'HEAD' && method !== 'DELETE') {
        // For multipart (file upload), stream the raw body
        if (req.headers['content-type']?.includes('multipart/form-data')) {
          // Can't easily re-stream multipart here — skip body forwarding
          // (ingest-assay uses its own dedicated handler above this wildcard)
        } else {
          // B3 — inject org_id into IND assembly bodies so the backend
          // _build_rag_context can load the per-org prompt_rules YAML +
          // few_shot_index. Matches both /ind-assembly and
          // /ind-assembly/supersede. Caller's org_id wins if already set.
          const u: any = (req as any).user;
          const isIndAssembly = /\/ind-assembly(?:\/supersede)?$/.test(targetPath);
          if (isIndAssembly && u) {
            const orgId =
              (u.organization && String(u.organization).trim()) ||
              (u.id ? String(u.id) : "");
            if (orgId && (!req.body || !req.body.org_id)) {
              req.body = { ...(req.body || {}), org_id: orgId };
            }
          }
          fetchOpts.body = JSON.stringify(req.body);
        }
      }

      const resp = await fetchGalaxyAsUser(req, `${galaxyUrl}${fullPath}`, fetchOpts);

      // Stream response back
      const contentType = resp.headers.get('content-type') || 'application/json';
      res.setHeader('Content-Type', contentType);
      res.status(resp.status);

      if (contentType.includes('application/json')) {
        const data = await resp.json().catch(() => ({}));
        return res.json(data);
      } else {
        // Stream binary/text
        const buf = Buffer.from(await resp.arrayBuffer());
        return res.send(buf);
      }
    } catch (err: any) {
      const status = err.response?.status || 502;
      const detail = err.response?.data || { error: 'Drug discovery proxy error', detail: err.message };
      return res.status(status).json(detail);
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // ─────────────────────────────────────────────────────────────────────────
  // IND attachments — dedicated multipart route BEFORE the /api/ind-report/*
  // wildcard. multer parses the multipart body into memory; we re-issue
  // a FormData request to the Galaxy backend so the backend sees a normal
  // file upload regardless of how the browser framed it.
  // A1 from docs/20260603_IND_MODULE_HONEST_AUDIT.md.
  // ─────────────────────────────────────────────────────────────────────────
  const _indUpload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 50 * 1024 * 1024 },
  });
  app.post(
    "/api/ind-report/projects/:projectId/attachments",
    optionalAuth,
    _indUpload.single("file"),
    async (req: any, res: any) => {
      try {
        const galaxyUrl = process.env.GALAXY_URL || 'http://localhost:8081';
        if (!req.file) {
          return res.status(400).json({ error: 'no file in multipart upload' });
        }
        const fd = new FormData();
        const blob = new Blob([req.file.buffer], {
          type: req.file.mimetype || 'application/octet-stream',
        });
        fd.append('file', blob, req.file.originalname || 'upload');
        const resp = await fetchGalaxyAsUser(req,
          `${galaxyUrl}/api/ind-report/projects/${encodeURIComponent(req.params.projectId)}/attachments`,
          {
            method: 'POST',
            headers: {},
            body: fd,
            signal: AbortSignal.timeout(120000),
          },
        );
        const data = await resp.json().catch(() => ({}));
        return res.status(resp.status).json(data);
      } catch (err: any) {
        return res.status(502).json({ error: 'ind attachment proxy error', detail: err.message });
      }
    },
  );

  // IND Report module — proxy /api/ind-report/* to Galaxy backend
  //   POST   /api/ind-report/projects/:id/sign
  //   POST   /api/ind-report/projects/:id/document.md  (returns text/markdown)
  //   POST   /api/ind-report/projects/:id/document.docx (returns Word blob)
  //   POST   /api/ind-report/projects/:id/snapshot
  //   GET    /api/ind-report/projects/:id/versions
  //   POST   /api/ind-report/projects/:id/sections/render
  //   POST   /api/ind-report/projects
  //   PATCH  /api/ind-report/projects/:id/compounds
  // ─────────────────────────────────────────────────────────────────────────
  app.all("/api/ind-report/*", optionalAuth, backendPassthrough("IND report"));

  // Proxy /api/regulatory/* to the Galaxy backend. These are galaxy-served routes
  // (active_adapter, generate_smoke, generate_stream, feedback/queue) that the
  // public frontend must expose for the IND PI suite + the ind-report UI — without
  // this they 404 on dev/prod (caddy routes the public domain to this Node server,
  // which had no /api/regulatory handler). Mirrors the /api/ind-report/* proxy
  // above. Does NOT shadow the frontend's own /api/regulatory_llm/* routes — the
  // `/api/regulatory/` prefix (trailing slash) cannot match `/api/regulatory_llm/`.
  app.all("/api/regulatory/*", optionalAuth, backendPassthrough("regulatory"));

  // Grounded Standards Assistant — evidence-tiered, provenance-honest answering.
  // Proxies POST /api/grounded/answer to the Galaxy backend router
  // (webapps/galaxy/api/grounded.py), which resolves the tenant from the
  // authenticated Galaxy session so isolation cannot be spoofed by the caller.
  // Mirrors the /api/regulatory/* proxy above.
  app.all("/api/grounded/*", optionalAuth, backendPassthrough("grounded"));

  // ─────────────────────────────────────────────────────────────────────────
  // DL upgrade wave-1/wave-2 — Models + Design&Generate surfaces.
  // Proxy the Galaxy-served WS1 endpoints to the browser, mirroring the
  // /api/ind-report/* and /api/regulatory/* proxies above (optionalAuth,
  // user's decrypted Galaxy API key with GALAXY_API_KEY fallback, JSON or
  // binary passthrough). Consumed by frontend components/models/* and
  // components/design-generate/*:
  //   GET  /api/models                       (registry list)
  //   GET  /api/models/:id                   (model object)
  //   POST /api/models/:id/infer             (submit inference)
  //   GET  /api/inference/:runId/result      (poll inference result)
  //   GET  /api/model-tracks/train           (Train track: training runs)
  //   GET  /api/model-tracks/adapt           (Adapt track: learned edit pairs)
  //   GET  /api/model-tracks/optimise        (Optimise track: DMTA loop)
  //   POST /api/generate                     (submit generation)
  //   GET  /api/generate/:runId              (poll generation run)
  // A single shared handler keeps behavior identical across all six.
  const _dlProxyHandler = backendPassthrough("DL surface");
  const _modelsOwnerProxy = async (req: any, res: any) => {
    try {
      const target = proxyTarget(req);
      if (!target.ok) return rejectProxyPath(res, target);
      await authorizeModelProject(req.user?.id, req.query.project, uid => memoryService.projects.getUserProjects(uid));
      const response = await fetchOwnedModelSurface(req.user?.id, `${target.path}${target.query}`, {
        method: req.method,
        ...(!['GET', 'HEAD'].includes(req.method) ? { body: JSON.stringify(req.body || {}) } : {}),
      });
      return res.status(response.status).json(await response.json().catch(() => ({ error: 'Invalid Models service response' })));
    } catch (error) {
      return res.status(error instanceof ModelSurfaceAccessError ? error.status : 502).json({ error: error instanceof ModelSurfaceAccessError ? error.message : 'Models service unavailable' });
    }
  };

  // Dedicated handler for the Adapt-track retrain: proxy to Galaxy (the job runs
  // synchronously there — queued → running → succeeded via the worker tick),
  // then register it as a FIRST-CLASS run so it appears in the Runs dashboard
  // alongside Nextflow runs. It is tagged workflow_type:"training" and
  // executionEngine:"pipeline" — never faked as a Nextflow subprocess. The run
  // reflects the terminal status Galaxy returned (no long-poll needed).
  const _adaptRetrainHandler = async (req: any, res: any) => {
    // 1) proxy to Galaxy exactly like _dlProxyHandler, but capture the JSON.
    let galaxyJson: any = {};
    let galaxyStatus = 200;
    try {
      const target = proxyTarget(req);
      if (!target.ok) return rejectProxyPath(res, target);
      await authorizeModelProject(req.user?.id, req.query.project, uid => memoryService.projects.getUserProjects(uid));
      const fullPath = `${target.path}${target.query}`;
      const resp = await fetchOwnedModelSurface(req.user?.id, fullPath, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(req.body || {}),
        signal: AbortSignal.timeout(120000),
      });
      galaxyStatus = resp.status;
      galaxyJson = await resp.json().catch(() => ({}));
      if (galaxyStatus >= 400) return res.status(galaxyStatus).json(galaxyJson);
      if (!isTrackedAdaptJob(galaxyStatus, galaxyJson)) return res.status(502).json({ error: 'Models service did not return a valid tracked training job.' });
    } catch (err: any) {
      const status = err instanceof ModelSurfaceAccessError ? err.status : err.response?.status || 502;
      return res.status(status).json({ error: 'DL surface proxy error', detail: err.message });
    }

    // 2) Best-effort: register a first-class run reflecting the job outcome.
    //    A failure to register must NOT change the API response the UI sees.
    try {
      const userId = (req as any).user?.id || undefined;
      const projectId = (req.query?.project as string) || undefined;
      // Galaxy job status → dashboard status vocabulary.
      const jobStatus = String(galaxyJson?.status || 'queued');
      const dashStatus: ExecutionRunStatus =
        jobStatus === 'succeeded' ? 'completed'
        : jobStatus === 'failed' || jobStatus === 'cancelled' ? 'failed'
        : jobStatus === 'running' ? 'running'
        : 'queued';
      const pairCount = galaxyJson?.edit_pair_count;
      const run = await storage.createExecutionRun(
        {
          workflowDefinition: {
            name: 'Adaptation retrain',
            // Not model training (no model, no metrics): kept out of the Models
            // panel's training-runs list, still a first-class run in Run Manager.
            workflow_type: 'adaptation',
            description:
              typeof galaxyJson?.message === 'string' && galaxyJson.message
                ? galaxyJson.message
                : 'Retrain over the active edit pairs (prompt-rules compile).',
            steps: {
              '1': { label: 'Compile edit pairs', tool_id: 'adapt_compile' },
            },
          },
          executionConfig: { mode: 'production', executionEngine: 'pipeline' },
        } as any,
        userId,
        projectId,
      );
      // Reflect the terminal status the job already reached.
      await storage.updateExecutionRunStatus(
        run.id,
        dashStatus,
        dashStatus === 'failed' ? String(galaxyJson?.message || 'retrain failed') : undefined,
      );
      if (dashStatus === 'completed') {
        await storage.updateExecutionRunProgress(run.id, 1, 0, 'Compile edit pairs');
      }
      // Surface the run id so the UI can deep-link to it.
      galaxyJson = { ...galaxyJson, runId: run.id, edit_pair_count: pairCount };
    } catch (e: any) {
      console.warn('[model-tracks] retrain run registration failed:', e?.message);
    }

    return res.status(galaxyStatus).json(galaxyJson);
  };

  // Bare-path matchers (Express "/*" wildcards require a following segment, so
  // the collection roots are registered explicitly) plus their sub-paths.

  // Structure "Run a model" → fold on OUR AWS Batch (Boltz-2), not NVIDIA.
  // Stages the sequence as a FASTA and returns the boltz_structure_prediction
  // launch request; the client submits it through POST /api/workflows/execute,
  // so the fold is a tracked run (see server/model-fold.ts).
  app.post("/api/models/fold/plan", authenticateToken, async (req: any, res) => {
    const result = await planModelFold({ userId: req.user?.id, body: req.body }, {
      stageFasta: async (content: string, basename: string) => {
        const onPrem = !!process.env.S3_ENDPOINT_URL;
        const bucket = onPrem
          ? (process.env.S3_BUCKET_NAME || 'biomate-data')
          : (process.env.NEXTFLOW_S3_BUCKET || process.env.AWS_S3_NEXTFLOW_BUCKET || 'biomate-nextflow-work');
        const { randomUUID } = await import('crypto');
        const key = `uploads/fold-${randomUUID()}/${basename}`;
        try {
          const { PutObjectCommand } = await import('@aws-sdk/client-s3');
          const s3 = await _s3ClientForBucket(bucket);
          await s3.send(new PutObjectCommand({ Bucket: bucket, Key: key, Body: content, ContentType: 'text/plain' }));
          return `s3://${bucket}/${key}`;
        } catch (error) {
          console.error('[fold] stageFasta failed:', error instanceof Error ? error.message : error);
          return undefined;
        }
      },
    });
    res.status(result.status).json(result.body);
  });
  app.all("/api/models", authenticateToken, _modelsOwnerProxy);
  app.all("/api/models/*", authenticateToken, _modelsOwnerProxy);
  // Project-scoped Models track reads (Train / Adapt / Optimise). Distinct
  // prefix so they don't fall under the greedy /api/models/:id detail route.
  // The retrain POST is registered FIRST (more specific) so it can register a
  // first-class run; everything else falls through to the shared proxy.
  // Training is execution activity, not a list of globally registered campaign scorers.
  // Keep real user/run identity so successful workflow training cannot disappear from Models.
  // Model registration is owner-scoped and uses only canonical outputs and the
  // recorded launch snapshot. Browser requests never supply paths/owners/metrics.
  const modelRegistrationDependencies = {
    listOutputs: async (runId: string) => {
      const { runsOutputsService } = await import("./services/runs-outputs-service");
      return runsOutputsService.list(runId);
    },
    internalRequest: requestInternalModelRegistry,
  };
  const modelRegistrationFailure = (res: any, error: any) => res.status(error instanceof TrainingRegistrationError ? error.status : 502).json({ error: error instanceof TrainingRegistrationError ? error.message : 'Central model registry is unavailable. Please retry.' });
  app.post("/api/model-training-activity/:runId/register", authenticateToken, async (req: any, res) => {
    if (req.body && Object.keys(req.body).length) return res.status(400).json({ error: 'Model registration accepts no client-supplied settings.' });
    const run = await resolveAuthorizedRun(req, res, req.params.runId);
    if (!run) return;
    try {
      const result = await registerOwnedTrainingRun(req.user?.id, run, modelRegistrationDependencies);
      return res.status(result.status).json(result.body);
    } catch (error) { return modelRegistrationFailure(res, error); }
  });
  app.get("/api/model-training-activity/:runId/versions", authenticateToken, async (req: any, res) => {
    const run = await resolveAuthorizedRun(req, res, req.params.runId);
    if (!run) return;
    try {
      const result = await readOwnedTrainingVersions(req.user?.id, run, modelRegistrationDependencies);
      return res.status(result.status).json(result.body);
    } catch (error) { return modelRegistrationFailure(res, error); }
  });
  app.get("/api/model-training-versions", authenticateToken, async (req: any, res) => {
    try {
      const projects = await memoryService.projects.getUserProjects(req.user.id);
      const project = req.query.project;
      if (project !== undefined && (typeof project !== 'string' || !projects.some((item: any) => item.id === project))) return res.status(403).json({ error: 'Project access denied' });
      const scopes: Array<string | undefined> = project ? [project] : [undefined, ...projects.map((item: any) => item.id)];
      const versions: any[] = [];
      for (const scope of new Set(scopes)) {
        const query = new URLSearchParams({ owner_id: req.user.id });
        if (scope) query.set('project_id', scope);
        const result = await requestInternalModelRegistry(`/api/internal/model-training/versions?${query}`);
        if (result.status !== 200) return res.status(result.status).json(result.body);
        versions.push(...(result.body.versions || []));
      }
      return res.json({ versions });
    } catch (error) { return modelRegistrationFailure(res, error); }
  });
  app.get("/api/model-tracks/train", authenticateToken, async (req, res) => {
    const result = await readModelTrainingActivity({ userId: req.user?.id, project: req.query.project }, {
      getUserProjects: uid => memoryService.projects.getUserProjects(uid),
      getExecutionRuns: (uid, project) => storage.getExecutionRuns(uid, project, undefined, 500),
      // The trainer writes results/metrics.json (metrics + gate) to the run's own outputs;
      // the URI comes from the run record (or Galaxy's status for it), never from the client.
      loadTrainingMetrics: async (run) => {
        const bucket = process.env.AWS_S3_NEXTFLOW_BUCKET || 'biomate-nextflow-work';
        const uriOf = (f: any) => (typeof f === 'string' ? f : f?.s3_uri || f?.path || f?.url || '') as string;
        let files: unknown[] = run.execution?.nextflowStatus?.s3_output_files || run.execution?.nextflowStatus?.output_files || [];
        if (!files.some((f) => /\/metrics\.json$/.test(uriOf(f))) && run.execution?.nextflowRunId) {
          const g = await fetch(`${process.env.GALAXY_URL || 'http://localhost:8081'}/api/nextflow/status/${encodeURIComponent(run.execution.nextflowRunId)}`,
            { signal: AbortSignal.timeout(8000) }).catch(() => null);
          const gd: any = g && g.ok ? await g.json().catch(() => null) : null;
          if (Array.isArray(gd?.s3_output_files)) files = gd.s3_output_files;
        }
        const uris = files.map(uriOf).filter((u) => u.startsWith(`s3://${bucket}/`) && /\/metrics\.json$/.test(u));
        const uri = uris.find((u) => /\/results\/metrics\.json$/.test(u)) || uris[0];
        if (!uri) return null;
        const { GetObjectCommand } = await import('@aws-sdk/client-s3');
        // The work bucket is in us-east-1, not the app region: a us-west-2 client
        // got PermanentRedirect on every read, so no run ever showed its score.
        const client = await _s3ClientForBucket(bucket);
        const obj = await client.send(new GetObjectCommand({ Bucket: bucket, Key: uri.slice(`s3://${bucket}/`.length) }));
        const text = await (obj.Body as any)?.transformToString?.('utf-8');
        return text && text.length < 512 * 1024 ? JSON.parse(text) : null;
      },
      saveTrainingSummary: async (runId, summary) => {
        const current = await storage.getExecutionRun(runId);
        if (!current) return;
        await storage.updateExecutionRun(runId, { execution: { ...(current as any).execution, trainingSummary: summary } } as any);
      },
    });
    res.status(result.status).json(result.body);
  });
  // Models panel → structured training plan (no chat draft). The returned
  // workflow_ga is submitted by the client through POST /api/workflows/execute.
  app.post("/api/model-training/plan", authenticateToken, async (req: any, res) => {
    const result = await planModelTraining({ userId: req.user?.id, body: req.body }, {
      getProjectFile: async (projectId, fileId, uid) => {
        const rows = await pool.query(`SELECT f.id, f.name, f.s3_key FROM project_files f JOIN projects p ON p.id = f.project_id
          WHERE f.id::text = $1 AND f.project_id::text = $2 AND (p.user_id::text = $3 OR EXISTS (
            SELECT 1 FROM project_members m WHERE m.project_id = p.id AND m.user_id::text = $3
          )) LIMIT 1`, [fileId, projectId, uid]);
        const row = rows.rows[0];
        return row ? { id: String(row.id), name: String(row.name), s3_key: String(row.s3_key) } : null;
      },
      listFolderFiles: async (projectId, folderPath, uid) => {
        const allowed = await pool.query(
          `SELECT 1 FROM projects p WHERE p.id::text = $1 AND (p.user_id::text = $2 OR EXISTS (
            SELECT 1 FROM project_members m WHERE m.project_id = p.id AND m.user_id::text = $2
          )) LIMIT 1`,
          [projectId, uid],
        );
        if (!allowed.rows.length) return [];
        const { loadFolderFiles } = await import('./project-folders');
        const rows = await loadFolderFiles((q, p) => pool.query(q, p), projectId, folderPath);
        return rows
          .filter((r) => r.id && r.s3_key)
          .map((r) => ({ id: String(r.id), name: String(r.name), s3_key: String(r.s3_key) }));
      },
      stageForBatch: async (file, projectId) => {
        const bucket = process.env.S3_BUCKET_NAME || '';
        if (!bucket) return undefined;
        return _stageProjectFileToNextflow(bucket, file.s3_key, projectId, file.name);
      },
      requestGalaxyPlan: async (uid, body) => {
        const response = await fetchOwnedModelSurface(uid, '/api/model-training/plan', {
          method: 'POST', body: JSON.stringify(body),
        });
        return { status: response.status, body: await response.json().catch(() => ({ error: 'Invalid training service response' })) };
      },
    });
    res.status(result.status).json(result.body);
  });
  app.post("/api/model-tracks/adapt/retrain", authenticateToken, _adaptRetrainHandler);
  app.all("/api/model-tracks/*", authenticateToken, _modelsOwnerProxy);
  app.all("/api/inference/*", authenticateToken, _modelsOwnerProxy);
